188	    /** A claim's due now: its amount at the rate, in force on the claim's date, for the grade its person
189	     *  had on that date, falling back to the parent sheets' (see {@link #rateInForce})
190	     *  (the one with the latest from-date on or before it; an undated rate applies from the beginning
191	     *  of time; none applies when the claim's date is after that rate's to-date), rounded to two decimals by the claim's
192	     *  rounding (see {@link #rounding}) — the rate figure, not floored: the floor is applied last, in {@link #dueNow};
193	     *  null when no rate applies. */
194	    public BigDecimal due(String sheetId, Claim claim) {
195	        BigDecimal pct = rateInForce(sheetId, claim.personId(), LocalDate.parse(claim.date()));
196	        if (pct == null) return null;
197	        BigDecimal due = new BigDecimal(claim.amount()).multiply(pct).movePointLeft(2)
198	                .setScale(2, rounding(sheetId, claim));
199	        return due;
