202	    /** How a claim's live figures round: half up when the claim is dated before the sheet's policy date
203	     *  (blank meaning the sheet's today), else half to even. A correction rounds by the date of the
204	     *  claim it corrects (its person's claim with that number), not its own. */
205	    public RoundingMode rounding(String sheetId, Claim claim) {
206	        String date = claim.date();
207	        if (claim.corrects() != null) {
208	            List<Date> corrected = jdbc.queryForList("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ?"
209	                    + " AND claim_no = ? ORDER BY id LIMIT 1", Date.class, sheetId, claim.personId(), claim.corrects());
210	            if (!corrected.isEmpty()) date = corrected.get(0).toLocalDate().toString();
211	        }
212	        List<Date> policy = jdbc.queryForList("SELECT COALESCE(policy_date, today) FROM sheet WHERE id = ?",
213	                Date.class, sheetId);
214	        if (policy.isEmpty()) return RoundingMode.HALF_EVEN;
215	        return LocalDate.parse(date).isBefore(policy.get(0).toLocalDate()) ? RoundingMode.HALF_UP
216	                : RoundingMode.HALF_EVEN;
217	    }
