219	    /** A claim's figure now: the due fixed when it was settled, else the one its last statement bound
220	     *  it to (not while PENDING; none when it bound it to n/a), else its live rate figure (not floored); null when it has none. */
221	    public BigDecimal figure(String sheetId, Claim claim) {
222	        if (claim.due() != null) return new BigDecimal(claim.due());
223	        if (claim.bound() && claim.statedNa()) return null;
224	        if (claim.bound() && claim.statedDue() != null) return new BigDecimal(claim.statedDue());
225	        return due(sheetId, claim);
226	    }
