245	    /** The day a claim's overdue days are counted from: its due-by plus the grace days, in force on the claim's date,
246	     *  of the grade its person had on that date (its due-by when that grade has no grace then). The claim is overdue
247	     *  while open, not deferred, and this day is before the sheet's today; its 30-day late charge boundaries count
248	     *  from it. */
249	    public LocalDate overdueFrom(String sheetId, Claim claim) {
250	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
251	        String grade = gradeOn(sheetId, claim);
252	        if (grade == null) return dueBy;
253	        Integer grace = settings.gradeGrace(sheetId, grade, LocalDate.parse(claim.date()));
254	        return grace == null ? dueBy : dueBy.plusDays(grace);
255	    }
