270	    /** The late charge on a claim's figure now (see {@link #dueNow}); zero when it is not overdue. */
271	    private BigDecimal lateCharge(String sheetId, Claim claim, BigDecimal figure) {
272	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
273	        if (!claim.open() || claim.deferred()) return charge;
274	        List<Date> found = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId);
275	        if (found.isEmpty()) return charge;
276	        LocalDate today = found.get(0).toLocalDate();
277	        LocalDate dueBy = overdueFrom(sheetId, claim);
278	        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / 30 : 0;
279	        if (periods == 0) return charge;
280	        RoundingMode rounding = rounding(sheetId, claim);
281	        for (long n = 1; n <= periods; n++) {
282	            BigDecimal pct = settings.latePct(sheetId, dueBy.plusDays(30 * n));
283	            if (pct == null || pct.signum() == 0) continue;
284	            charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
285	        }
286	        return charge;
287	    }
