304	    /** The rate (a percent) in force on a date for the grade the person has on that date: this sheet's (see
305	     *  {@link #RATE_FOR}) when it has one in force then (not past its to-date), else its parent sheet's for that
306	     *  grade and date, then the parent's parent's, up to three levels up; null when none is. */
307	    public BigDecimal rateInForce(String sheetId, long personId, LocalDate on) {
308	        List<String> grade = jdbc.queryForList("SELECT " + GRADE_ON + " FROM DUAL", String.class, sheetId,
