315	            List<BigDecimal> pct = jdbc.queryForList("SELECT a.pct FROM " + RATE_FOR + " a"
316	                    + " WHERE a.to_date IS NULL OR a.to_date >= CAST(? AS DATE)", BigDecimal.class,
317	                    at, grade.get(0), on.toString(), on.toString());
318	            if (!pct.isEmpty()) return pct.get(0);
319	        }
320	        return null;
321	    }
