421	    /** Re-fix, after a holiday is added to the sheet, the due-by of each claim not SETTLED or VOID whose due-by is on
422	     *  or after it: the terms-th business day after its date over the sheet's holidays now, for the terms it was fixed
423	     *  with (the business days from its date to its due-by over the holidays before, {@code before}). A claim whose
424	     *  due-by moves is kept in the history. */
425	    public void refixDueBy(String sheetId, java.util.Set<String> before, LocalDate holiday) {
426	        java.util.Set<String> now = new java.util.HashSet<>(before);
427	        now.add(holiday.toString());
428	        List<Object[]> open = jdbc.query("SELECT id, claim_date, due_by FROM claim WHERE sheet_id = ?"
429	                + " AND status NOT IN ('SETTLED', 'VOID') AND due_by >= ? ORDER BY id",
430	                (rs, i) -> new Object[] { rs.getLong("id"), rs.getDate("claim_date").toLocalDate(),
431	                        rs.getDate("due_by").toLocalDate() }, sheetId, Date.valueOf(holiday));
432	        for (Object[] c : open) {
433	            LocalDate date = (LocalDate) c[1];
434	            LocalDate old = (LocalDate) c[2];
435	            LocalDate fixed = SettingsRepository.businessDaysAfter(now, date, businessDaysBetween(before, date, old));
436	            if (fixed.equals(old)) continue;
437	            jdbc.update("UPDATE claim SET due_by = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(fixed), c[0], sheetId);
438	            history.claim(sheetId, (Long) c[0]);
439	        }
440	    }
