442	    /** The business days (not a Saturday, Sunday or one of the holidays) after a date up to and including another. */
443	    private static int businessDaysBetween(java.util.Set<String> holidays, LocalDate from, LocalDate to) {
444	        int days = 0;
445	        for (LocalDate d = from.plusDays(1); !d.isAfter(to); d = d.plusDays(1)) {
446	            java.time.DayOfWeek day = d.getDayOfWeek();
447	            if (day != java.time.DayOfWeek.SATURDAY && day != java.time.DayOfWeek.SUNDAY && !holidays.contains(d.toString())) {
448	                days++;
449	            }
450	        }
451	        return days;
452	    }
