556	    /** Whether an external reference is already used by a claim on the sheet other than {@code exceptId} (null: any),
557	     *  comparing without regard to case. */
558	    public boolean refUsed(String sheetId, String ref, Long exceptId) {
559	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND ref IS NOT NULL AND LOWER(ref) = LOWER(?)"
560	                + " AND id <> ?", Integer.class, sheetId, ref, exceptId == null ? -1L : exceptId);
561	        return n != null && n > 0;
