564	    /** Lock a claim for {@code by}'s editor, releasing any other claim of the same person {@code by} held;
565	     *  false when another user holds the claim's lock. */
566	    public boolean lock(String sheetId, Claim claim, String by) {
567	        if (jdbc.update("UPDATE claim SET locked_by = ? WHERE id = ? AND sheet_id = ?"
568	                + " AND (locked_by IS NULL OR locked_by = ?)", by, claim.id(), sheetId, by) == 0) {
569	            return false;
570	        }
571	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND person_id = ? AND locked_by = ? AND id <> ?",
572	                sheetId, claim.personId(), by, claim.id());
573	        return true;
574	    }
