586	    /** Who holds a claim's lock; null when it is not locked. */
587	    public String lockedBy(String sheetId, long claimId) {
588	        List<String> found = jdbc.queryForList("SELECT locked_by FROM claim WHERE id = ? AND sheet_id = ?", String.class,
589	                claimId, sheetId);
590	        return found.isEmpty() ? null : found.get(0);
