593	    /** Make the sheet's next settle batch and give it to these claims: its number (1, 2, ... on the sheet). */
594	    public int batch(String sheetId, List<Long> claimIds) {
595	        jdbc.update("UPDATE sheet SET last_batch = COALESCE(last_batch, 0) + 1 WHERE id = ?", sheetId);
596	        int batch = lastBatch(sheetId);
597	        for (Long cid : claimIds) {
