612	        jdbc.query("SELECT id, batch FROM claim WHERE sheet_id = ? AND batch IS NOT NULL",
613	                rs -> {
614	                    batches.put(String.valueOf(rs.getLong("id")), rs.getInt("batch"));
615	                }, sheetId);
