633	        if (claim == null) return;
634	        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due)"
635	                + " SELECT ?, ?, ?, ?, today, ? FROM sheet WHERE id = ?",
