import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { useEffect, useId } from 'react';

// The actions on a person's row (statement, hold, retire) live in separate slots, but share the row's one
// `person-error`. Taking any of them announces it on the row, and every other action there clears its old
// error, so a refusal left by one action never shows beside (or for) the next.
const bus = new EventTarget();

/** Clear this action's error (`reset`) when another action on the same row is taken; returns the
 *  `announce` to call as this action is taken. */
export function usePersonRowAction(sheetId: string, personId: number, reset: () => void): () => void {
  const self = useId();
  const row = `${sheetId}/${personId}`;
  useEffect(() => {
    const listener = (e: Event) => {
      const d = (e as CustomEvent<{ row: string; from: string }>).detail;
      if (d.row === row && d.from !== self) reset();
    };
    bus.addEventListener('person-action', listener);
    return () => bus.removeEventListener('person-action', listener);
  }, [row, self, reset]);
  return () => bus.dispatchEvent(new CustomEvent('person-action', { detail: { row, from: self } }));
}
package net.officefloor.hq.app.settings;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.history.AsOfView;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuse any change from a screen showing the sheet as of a date, any change by a viewer of the sheet, and any change at all to an archived sheet (400, nothing written). The first step of every endpoint
 *  that changes a sheet, except the bulk ones, where a viewer's selection is simply all refused. */
public class RefuseViewer {
    public void refuse(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            SettingsRepository settings) throws BadRequestException {
        String by = CurrentUser.require(connection);
        AsOfView.refuse(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (settings.archived(id)) {
            throw new BadRequestException("the sheet is archived");
        }
        if (settings.role(id, by).equals(SettingsRepository.VIEWER)) {
            throw new BadRequestException("a viewer can change nothing");
        }
    }
}
