test("transfer person scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "terms", "7");
  await ui.setSetting(pg_uma, "terms-A", "3");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-01");
  await ui.setSetting(pg_uma, "grace-B", "5");
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  await ui.setSetting(pg_uma, "pot", "100.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50", "from": "2026-03-01"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ben_2 = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "terms": "3"}));
  const p_ada_2 = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "60.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "40.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00", "from": "2026-03-10", "to": "2026-03-12"})).toBe(true);
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  expect(await ui.ratePreview(pg_uma, "B", "10.00")).toEqual({ count: 0, diff: "0.00" });
  expect(await ui.statement(pg_uma, p_ada_2)).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.periodAction(pg_wes, "P1", "reopen")).toBe(true);
  expect(await ui.setSettingDated(pg_wes, "cap", "5.00", "2026-02-25", "2.00")).toBe(true);
  expect(await ui.statement(pg_wes, p_ben_2)).toBe(true);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("header-people-count")).toHaveText("2");
  expect(await ui.setRate(pg_wes, {"grade": "C", "pct": "33.33", "from": "2026-03-10"})).toBe(true);
  await ui.refresh(pg_uma);
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben_2, {"amount": "7.77", "tags": "b,a,a"}));
  const c_ada_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Ada", "amount": "25.00"}, p_ada_2));
  expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
  expect(await ui.setSettingDated(pg_uma, "note-threshold", "", "2026-03-05", "")).toBe(true);
  await ui.setToday(pg_uma, "2026-04-28");
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ben_2).getByTestId("person-claimed")).toHaveText("7.77");
  await expect(pg_uma.getByTestId("person-row-" + p_ben_2).getByTestId("person-due-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("1.25");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("7.77");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("rollup-open-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("header-people-count")).toHaveText("2");
  await expect(pg_uma.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("header-claims-OPEN-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("header-due-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("1.00");
  await ui.refresh(pg_wes);
  expect(await ui.reassign(pg_wes, c_ben_0, "Ada")).toBe(true);
  expect(await ui.periodAction(pg_wes, "P1", "close")).toBe(true);
  expect(await ui.claimAction(pg_wes, c_ada_0, "open")).toBe(true);
  expect(await ui.statementAsOf(pg_wes, p_ben_2, "2026-03-05")).toBe(false);
  expect(await ui.addProof(pg_wes, c_ada_0)).toBe(true);
  const c_ada_2 = ui.must(await ui.addClaim(pg_wes, p_ada_2, {"amount": "99.95", "date": "2026-03-28", "note": "n", "tags": "a"}));
  await ui.setAsOf(pg_wes, "2026-03-28");
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("sheet-asof")).toHaveText("2026-03-28");
  await expect(pg_wes.getByTestId("sheet-parent")).toHaveText(`${sheet}-p`);
  await expect(pg_wes.getByTestId("consolidated-people-count")).toHaveText("2");
  await expect(pg_wes.getByTestId("consolidated-due-total")).toHaveText("2.00");
  await expect(pg_wes.getByTestId("consolidated-overdue-total")).toHaveText("2.25");

